create table alert_sends (
  idempotency_key text primary key,
  channel text not null check (channel in ('email','sms')),
  user_id uuid not null references profiles(id) on delete cascade,
  property_id uuid not null references properties(id) on delete cascade,
  violation_id uuid references violations(id) on delete set null,
  reminder_id uuid references violation_reminders(id) on delete set null,
  external_id text,
  sent_at timestamptz not null default now()
);
create index idx_alert_sends_user_time on alert_sends(user_id, sent_at desc);
create index idx_alert_sends_property on alert_sends(property_id, sent_at desc);

create table cron_runs (
  id uuid primary key default gen_random_uuid(),
  run_date date not null default current_date,
  property_id uuid,
  phase text not null check (phase in ('scan','alert_email','alert_sms','reminder','score_snapshot','enrichment')),
  duration_ms int,
  ok boolean not null,
  error text,
  created_at timestamptz not null default now()
);
create index idx_cron_runs_date_phase on cron_runs(run_date, phase);
create index idx_cron_runs_property on cron_runs(property_id, created_at desc) where ok = false;

-- violations hot paths
create index concurrently if not exists idx_violations_property_status on violations(property_id, violation_status);
create index concurrently if not exists idx_violations_needs_alert on violations(needs_alert) where needs_alert = true;
create index concurrently if not exists idx_violations_property_firstseen on violations(property_id, first_seen_at desc);
create index concurrently if not exists idx_violations_user_resolution on violations(property_id, user_resolution_status) where user_resolution_status in ('open','pending_verification');
create index concurrently if not exists idx_violations_external_id on violations(external_id);
create index concurrently if not exists idx_violations_severity on violations(property_id, severity_classification);

-- resolutions
create index concurrently if not exists idx_resolutions_property on violation_resolutions(property_id);
create index concurrently if not exists idx_resolutions_external_id on violation_resolutions(violation_external_id);
create index concurrently if not exists idx_resolutions_user on violation_resolutions(user_id, created_at desc);

-- compliance events
create index concurrently if not exists idx_compliance_events_property_type_time on compliance_events(property_id, event_type, created_at desc);
create index concurrently if not exists idx_compliance_events_user_time on compliance_events(user_id, created_at desc);

-- analytics events
create index concurrently if not exists idx_analytics_user_path_time on analytics_events(user_id, page_path, created_at desc);
create index concurrently if not exists idx_analytics_type_time on analytics_events(event_type, created_at desc);

-- score history
create index concurrently if not exists idx_score_history_property_date on compliance_score_history(property_id, snapshot_date desc);

-- reminders
create index concurrently if not exists idx_reminders_active_nextrun on violation_reminders(next_reminder_at) where is_active = true;
create index concurrently if not exists idx_reminders_active_deadline on violation_reminders(deadline_date) where is_active = true;

-- properties
create index concurrently if not exists idx_properties_user on properties(user_id);
create index concurrently if not exists idx_properties_city on properties(city_id);
create index concurrently if not exists idx_properties_last_scanned on properties(last_scanned_at);
create index concurrently if not exists idx_properties_user_city on properties(user_id, city_id);

-- Example for analytics_events (similar pattern for others)
-- Step 1: create partitioned replacement
create table analytics_events_new (like analytics_events including defaults including constraints) partition by range (created_at);

-- Step 2: create partitions for current + next 3 months
create table analytics_events_2026_04 partition of analytics_events_new for values from ('2026-04-01') to ('2026-05-01');
create table analytics_events_2026_05 partition of analytics_events_new for values from ('2026-05-01') to ('2026-06-01');
create table analytics_events_2026_06 partition of analytics_events_new for values from ('2026-06-01') to ('2026-07-01');
create table analytics_events_2026_07 partition of analytics_events_new for values from ('2026-07-01') to ('2026-08-01');

-- Step 3: copy data (run off-hours, in batches for large tables)
insert into analytics_events_new select * from analytics_events;

-- Step 4: verify counts match, then swap
alter table analytics_events rename to analytics_events_old;
alter table analytics_events_new rename to analytics_events;

-- Step 5: recreate indexes on the partitioned parent
create index on analytics_events(user_id, page_path, created_at desc);
create index on analytics_events(event_type, created_at desc);

-- Step 6 (after verifying): drop _old table
-- drop table analytics_events_old;

-- Severity classification must always be set (moat data)
update violations set severity_classification = 'moderate' where severity_classification is null;
alter table violations alter column severity_classification set default 'moderate';
alter table violations alter column severity_classification set not null;
alter table violations add constraint chk_severity_valid check (severity_classification in ('critical','high','moderate','low','administrative'));

-- Score history range
alter table compliance_score_history add constraint chk_score_range check (score between 0 and 100);
alter table compliance_score_history add constraint chk_grade_valid check (grade in ('A','B','C','D','F'));

-- violation_external_id must be preserved in resolutions (moat data)
update violation_resolutions set violation_external_id = (select external_id from violations where violations.id = violation_resolutions.violation_id) where violation_external_id is null;
alter table violation_resolutions alter column violation_external_id set not null;

-- Cost sanity checks (prevent typos destroying analytics)
alter table violation_resolutions add constraint chk_exact_cost_positive check (exact_cost is null or exact_cost >= 0);
alter table violation_resolutions add constraint chk_exact_cost_reasonable check (exact_cost is null or exact_cost <= 500000);

-- Unique constraint on (property_id, external_id) to prevent duplicate violations on rescan
create unique index if not exists ux_violations_property_external on violations(property_id, external_id) where external_id is not null;

-- Email/phone format sanity
alter table profiles add constraint chk_email_format check (email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$');

-- Plan must be one of expected values
alter table profiles add constraint chk_plan_valid check (plan in ('free','starter','pro'));

alter table violations set (autovacuum_vacuum_scale_factor = 0.05, autovacuum_analyze_scale_factor = 0.02);
alter table analytics_events set (autovacuum_vacuum_scale_factor = 0.05, autovacuum_analyze_scale_factor = 0.02);
alter table compliance_events set (autovacuum_vacuum_scale_factor = 0.05, autovacuum_analyze_scale_factor = 0.02);
alter table violation_reminders set (autovacuum_vacuum_scale_factor = 0.1);

alter table properties add column if not exists city_slug text;
update properties set city_slug = cities.slug from cities where cities.id = properties.city_id;
create index if not exists idx_properties_city_slug on properties(city_slug);

alter table profiles add column if not exists email_bounced boolean not null default false;
alter table profiles add column if not exists email_suppressed boolean not null default false;
create table email_suppressions (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  reason text not null check (reason in ('bounce','complaint','manual','unsubscribe')),
  event_data jsonb,
  created_at timestamptz not null default now()
);
create unique index ux_email_suppressions_email on email_suppressions(email);

create table stripe_webhook_events (
  event_id text primary key,
  event_type text not null,
  processed_at timestamptz not null default now(),
  payload jsonb
);

-- Pattern for each new user-scoped table
alter table failed_alerts enable row level security;
create policy "users see own failed alerts" on failed_alerts for select using (user_id = auth.uid());

alter table alert_sends enable row level security;
create policy "users see own alert sends" on alert_sends for select using (user_id = auth.uid());

alter table property_stats enable row level security;
create policy "users see own property stats" on property_stats for select using (user_id = auth.uid());
-- Repeat for all new tables
-- Service role bypasses RLS; no explicit policy needed.

create table archived_resolutions (like violation_resolutions including all);
alter table archived_resolutions add column archived_at timestamptz not null default now();
alter table archived_resolutions add column archive_reason text;

create or replace function archive_resolutions_on_violation_delete() returns trigger as $$
begin
  insert into archived_resolutions select *, now(), 'violation_deleted' from violation_resolutions where violation_id = old.id;
  return old;
end; $$ language plpgsql;

create trigger trg_archive_resolutions before delete on violations
  for each row execute function archive_resolutions_on_violation_delete();
